const fs = require('fs');
const indexHtml = fs.readFileSync('dist/index.html', 'utf8');

// Extract the hashed CSS and JS URLs generated by Vite
const cssMatch = indexHtml.match(/href="(\/assets\/[^"]+\.css)"/);
const jsMatch = indexHtml.match(/src="(\/assets\/[^"]+\.js)"/);
const cssUrl = cssMatch ? cssMatch[1] : '';
const jsUrl = jsMatch ? jsMatch[1] : '';

console.log('Detected CSS:', cssUrl);
console.log('Detected JS:', jsUrl);

const replaceLinks = (dir) => {
  if (!fs.existsSync(dir)) return;
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const fullPath = dir + '/' + file;
    if (fs.statSync(fullPath).isDirectory()) {
      replaceLinks(fullPath);
    } else if (fullPath.endsWith('.html')) {
      let content = fs.readFileSync(fullPath, 'utf8');
      
      // Replace references to the uncompiled source files with the compiled Vite assets
      content = content.replace(/href="\/style\.css"/g, `href="${cssUrl}"`);
      content = content.replace(/href="(\.\.\/)*style\.css"/g, `href="${cssUrl}"`);
      content = content.replace(/src="\/src\/main\.js"/g, `src="${jsUrl}"`);
      content = content.replace(/src="(\.\.\/)*src\/main\.js"/g, `src="${jsUrl}"`);
      
      fs.writeFileSync(fullPath, content);
    }
  }
};

replaceLinks('dist/pages');
replaceLinks('dist/products');
replaceLinks('dist/collections');
console.log('Successfully updated all statically generated pages to use compiled assets.');
